with kept_keys as (select id, status from shipments intersect all select id, status from shipments where order_id is null), kept_rows as (select s.* from shipments s join kept_keys k on s.id = k.id and s.status = k.status), joined as (select e.order_id, e.shipped_date, e.delivered_date, p.status as order_status, p.channel from kept_rows e left join orders p on e.order_id = p.id), base as (select *, datediff(shipped_date, delivered_date) / 7 as weeks_delivered_date_to_shipped_date from joined where shipped_date > date '2023-02-12' and channel is not null), cleaned as (select *, concat_ws('/', order_status, channel) as order_status_channel_key from base where order_status is not null), matched_keys as (select order_id from cleaned intersect all select order_id from shipments where delivered_date < '2025-09-01'), reconciled as (select s.* from cleaned s join matched_keys k on s.order_id = k.order_id) select * from (select order_id, channel, weeks_delivered_date_to_shipped_date from reconciled) src pivot (sum(weeks_delivered_date_to_shipped_date) as amount, count(1) as item_count for channel in ('partner' as partner, 'web' as web));
